) AS (
  VALUES 
    (579::BIGINT, 'El profe es demasiado bueno, explica muy claro, da buena retroalimentacion y es bastante amable respondiendo las consultas, lo único es que los exámenes valen mucho, pero tampoco son exámenes pegados al cielo, con él se aprende mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'c40cd66c42162f81e983f2221df9a4e275bb4ff171caf0f0f1cda76b1abe3e7d'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'El profesor es muy bueno y uno aprende, pero los exámenes valen 90% de la nota entonces hay que ir demasiado preparado y básicamente solo los exámenes importan.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b09b15cfe1cf6cf9587c74784e1875a37c67297ca88772fd112a74a16ab221c2'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'El profesor es bueno, sin embargo, si usted desea matricular este curso en bloque completo la verdad es que no es recomendado. El curso lo evalua con un 90% examenes, lo cual hace que la dificultad del mismo aumente, cuando en realidad es un curso practicamente introductorio. No se los recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'f65e11416039cedcbc0d13bf0c08e4388e2ae543751acd5bdb5c3d7f9a172869'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Las clases son muy cansada porque la materia es muy densa, deja 6 trabajos semanales en los cuales hay que resumir videos o lecturas, realiza 4 quices y 4 proyectos. Los proyectos requieren tiempo, principalmente para investigar, consultar y demás. Sí estás interesado se aprende mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '1a617655ceee96f6aeb954954126809c876d5ccd4e13636bf58dd5fbc983cc74'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Excelente profe, sabe demasiado sobre la materia, ayuda muchísimo, explica las veces que sean necesarias para entender, da muchos ejemplos y material útil para no tener que buscar nada durante una progra, con su material se resuelve en dos toques. 100% recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c55b1c72f4a4b5088fc94cf2aefa44841c6ebe45d71bed98ff8c05ed9a3c577c'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Si usted no sabe programar, va a aprender muy fácil con este profe. Es sumamente carismático y muy buen profe. Explica super claro y pone muchos ejercicios y ejemplos para que uno practique bastante. Meta el curso sin miedo con este profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'a19e1afdd870a6ec39366ea91b8d7bea89f672b6c488bbf5e271e7f2f300f754'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Señor profesor! que calidad de docente: sabe enseñar, sabe escuchar, sabe de IA hasta decir basta, explica con manzanas. La U debería contratar más profesores así, comprometidos con transmitir sus conocimientos y comprometidos con ayudar al estudiante. No va encontrar un mejor profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8525cbe263148616e397a2b2796835c8fa1cae6542410640ec5a7fb9c685494f'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'No se puede pedir más de una clase de IA, de lo mejor que tiene la escuela. Brinda mucho material de calidad, de manera que para las tareas programadas muchas veces no fue necesario googlear nada (porque con el material de referencia fue suficiente para resolver).'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2083f58c5397f537b31c345bf2c6e00ae10f97840bb43e1434d856a6d7f2e7d8'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Realmente da un curso de ELEMENTOS no como otros que se van más allá. Lo recomiendo muchísimo, explica muy claro. En verano las clases son largas, pero hace recesos y son llevaderas. Califica justo y las evaluaciones son al nivel de lo que se ve en clase. Póngale y con suerte hasta se exime. (:'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-01-26T00:00:00+00:00'::TIMESTAMPTZ, '6bc9c5038851cbf0499e89c31d88a7485f47081f37aa2510d69ceb44c47e2578'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Excelente profesor, lleve el curso en verano y siempre fue muy claro y ordenado con todo si usted quiere practicar más, pídale práctica. Los exámenes tienen la misma dificultad de los ejercicios en clase entonces el curso es muy llevadero'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-24T00:00:00+00:00'::TIMESTAMPTZ, '04b8e1029ae08f6dbd356ab5badbb16d581b161744bce6957a5637e5d9877c89'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Lo único malo del profe es que no deja tarea para hacer, entonces uno casi no practica. Por lo demás, excelente profesor y persona.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '48efe0e7ec1a4e868eef57d456e1816861f30bddab5f4e82558a3d4a0d9baeb1'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Es un profesor de pies a cabeza, dedicado a su labor, nota si la clase no entendió algo, se preocupa por la carga académica respecto a la tareas que deja. Siempre va a estar dispuesto a reunirse con uno para repasar algo del curso o explicar alguna tarea o duda. Es una teja de profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '43ed5977061a8f9f321e0df4b4579dd5acf9970f4971634a144d3fa00246c89d'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'El profe es muy apasionado con el tema, y en modo virtual las clases están bastante bien. Todas las semanas se entrega una tarea o hace un quiz, pero no son tan complicad@s. Triste saber que no hay una extensión a este curso porque uno apenas raspa lo demasiado básico y queda un toque decepcionado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8397beae9f62a6a3841830c7ab84bfecaacfc767bb043a8c8c9fd66a0dc8ebe0'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'La clase es extremadamente pesada por ser de 4 horas, pero el profe es increíble, sabe muchísimo del tema y le encanta, le enseña a uno desde lo más básico hasta cosas bastante avanzadas, lo único malo es que son tareas todas las semanas algunas facílisimas y otras que se llevan su rato.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'df894e3806239d0126198e5c30aadee8f5596d4ce9bdd3d58a6ff526c7f87a23'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Muy accesible el profesor en la virtualidad, temas actualizados, bastantes tareas prácticas todas las semanas pero sencillas, realmente no alcanzan 16 semanas para tantos temas de este gran campo de la computación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '4618970c0823cdf56a5055fb8189f576c7f38b94e88810205918f3041b759527'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'En modo virtual fue super buen profe...siempre atento, busca que el estudiante de verdad entienda la materia. Se hacen como 10 quices (al final de la clase), 2 proyectos grupales y 3 exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '6958075283b15d2871f539da4db90f5fe48525ccbb8d22d94b8b42ac292ab3ce'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'El profe cambió los contenidos del curso y pudimos ver muchas de las ramas de la IA, tareas y quices casi todas las semanas, los proyectos son fáciles son como una tarea con documentación (algunas tareas no son muy fáciles y/o requieren buen tiempo) además solo hay un examen al final del curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '9aadb668093532e571feaf67cb98deaacc1f46a3bd691747ef7fef99d8a602ea'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Buen profe, los temas son bastante actuales. Ayuda mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '3761edfbce8bc08c497771310ecd4481bb6817d467f2bf93dfeedd0388e3c66e'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Sabe mucho del tema es experto en IA. Las clases se hacen un poco largas por que quiere abarcar mucha materia. En general es buen profe aunque no el mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e216701749a2a80ce20fb381117be1c84db97ebcfdf5a7ef207940373ad13ff7'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Es bueno profe, nada mas que en cuanto a IA esta un poco flojo, no senti que aprendi mucho en si de IA, pero el curso es facil, aprendi algunas bases y tuve una buena nota, no me quejo solo me gustaria que uno pudiera aprender mucho mas de lo que es realmente IA. Proyectos y tareas sumamente aburrid'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-09-28T00:00:00+00:00'::TIMESTAMPTZ, 'c288282b641e8316be9407b99937996cddeaa286d5b2cda557a1aee969f6d0a8'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Es un excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'b631e5a975a1bccdfa56e12d7602f2fbe746c80115da6da68e51eef3fc943127'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Bastante organizado, muy paciente y respetuoso, excelente persona. El único problema es que no da demasiado de IA. Lo siento medio flojo y es un regalo y los proyectos son mínimamente interesantes. Eso sí, es un regalo de curso.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '50de43acd548c064f400c90343eb66fe70d8baeec787af6bc32e8d3bc6f979ac'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Muy buen profe, se ve que sabe de lo que está hablando y orienta mucho la explicación a casos reales. En general, la evaluación hace que se pase bastante fácil si cumple con las tareas que pone todas las semanas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '15bc8721e0657c064a050b8db33bd00b2da89a2854513aa465155efa416eec0d'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'Es un crack, pues su área de especialidad es esta. Distribuye bien la nota durante el semestre entonces al final ya casi que se pasó el curso. Ayuda en lo que uno necesite y se ve que sabe de los temas. Recomendado si quiere aprender!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '0c832a9b9e63adff0ac0a047f058abbb73ae8255195068c10db0c790a639a25c'::TEXT, ARRAY[1162]::BIGINT[]),
    (579::BIGINT, 'EL profe explica demasiado claro y repite todas las veces necesario. Aunque explique como si fuera una clase para chiquitos si se avanza en la materia y si alguno juega de salsa lo frena. Con solo ir a las clases se pasa facil y se aprende.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '2efbd7b273722d8a95e5021e933590b1908e5fa04af60437af7ec61dadb3934e'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Explica demasiado bien, es super pura vida y todo queda super claro, explica las veces que sea necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, '40caba2b026fa3202223f5e50ff9d8c637f611134debcd7c384a3763da2c66ba'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Explica muy bien y se aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '4762ad9b8aca3bc79ca9f3e00832e3a7baafba80137feab0d9c7ecb7b183aea8'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Excelente profesor y persona, es demasiado comprensivo, intenta ayudar lo más posible y explica demasiado bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7b4cbd3cca49f45fe170f0d44a31d5cdb049f5ff1436e4fac2fab7e48c350519'::TEXT, ARRAY[315, 4866]::BIGINT[]),
    (579::BIGINT, 'Es el mejor profe que pueden tener'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '84e877cf28c8b2332cf65afa1614c3996a7d97a312158513ddb224de9fe982d3'::TEXT, ARRAY[1020]::BIGINT[]),
    (579::BIGINT, 'Si tiene la oportunidad de meter algún curso con él, HAGALO. Explica muy bien, siempre está ahí para los estudiantes. Recompenza el esfuerzo de los que le ponen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '19d6f2c91131eaf10490c951bf140520c8890ff94bb26faca237e269bcd7d6de'::TEXT, ARRAY[315, 4866]::BIGINT[]),
    (579::BIGINT, 'Una muy buena persona, tiene mucha paciencia, siempre esta dispuesto a ayudarle a uno. Progras no son tan complejas, valora el esfuerzo del estudiante. Perfecto para alguien que no te relacionas con el mundo de la programación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '46687ee16bd3afa0d0b377a45f168cb99e7d7691ea3c05c63455b13907688e74'::TEXT, ARRAY[315, 1022]::BIGINT[]),
    (579::BIGINT, 'Muy buen profesor, se preocupa mucho porque los contenidos sean adquiridos por el estudiante, y aún más si se va a la práctica profesional o trabajo. Muy apegado a calificar las cosas según al reglamento, pero está bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '3d69b0e7212f8f7972be1c768a2bc1b2ec297bfa60dae18d0a56a75e8a44bb41'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'Ya han dicho mucho en los comentarios anteriores, los cuales son ciertos. Es un buen profesor para esta materia, es súper organizado y muy respetuoso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '574ef357858eaf2c30b21bb00320d53b5c24a8465dbeee4e263373b6f12a0649'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'la clase la hace llevadera para ser un curso de contenido teórico y algo tedioso, siempre lleva invitados y lo hace a uno pensar sobre los temas, el proyecto es muy fácil, el examen también, hay tareas casa cierto tiempo pero muy sencillas, vale la pena y no se vuelve una carga el académica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '84004c2e130d319f74fb9087db2b637c5036813a92a23aa1fc727d53a1d8991e'::TEXT, ARRAY[1156]::BIGINT[]),
    (579::BIGINT, 'Trae invitados a clases seguido, a hablar de diferentes temas por lo que se aprende muchas cosas de muchos ámbitos de parte de gente especializada en esas áreas. La mayoría de trabajos se hacen en clases y no son complicados. Respeta mucho la opinión de los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'fc0e9da420b023329015d7baa1685c6a0a68f90913260295e1047ae06156f422'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'En general es un buen profe, aunque a veces divaga mucho cuando explica algunos temas. Me gustó mucho que invitara a gente de alto nivel, eso le da muchos puntos para ser una clase distinta y que aporte más al estudiante que de verdad ponga atención e interés.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'dca4f22c28ece0982096068a9750a816fd081221164c4fef5f82720c9d8bec4b'::TEXT, ARRAY[1156]::BIGINT[]),
    (579::BIGINT, 'Es un profe demasiado aburrido, habla de temas poco interesantes, las tareas y dinámicas en el curso son demasiado aburridas y de poco interés, el mae hace un curso en el cuál uno antes de ir piensa "que aburrido, otra aburrida clase de c&s",aparte los temas que el mae abarca son poco actualizados.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-04-29T00:00:00+00:00'::TIMESTAMPTZ, '19722f4fcddc35ba33cc994de9b3c4421665d5f075f3874e341d5bcd0f4d2515'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'Para mi no siguió el programa del curso. Se la pasa hablando, pero eso no es lo mismo que enseñar. Creo que sus conocimientos están un poco viejos.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Exámenes retadores', 'La participación importa']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'e4112374ac3374f15dafc8d49396fd3072010037dbf07fb0e38cdcd4bb36fcb4'::TEXT, ARRAY[1156]::BIGINT[]),
    (579::BIGINT, 'Explica super bien, ayuda bastante, sin embargo los exámenes si son bastante difíciles sumado a que no deja tarea por lo tanto queda a responsabilidad de cada quien buscarse práctica.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'f9cb257e95e4ffccdde8f83c6e5be8ca806574e3ac33d8311d33278254121a8d'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Excelente , explica como para niños ... Si tiene que repetir una explicación mil veces lo hace .Además no deja tareas y califica Justo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '6b3f5d63c09e7b5978c6a110dc7e04d23e29fc370d987066e0a4d451e0d91d7a'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'No estoy seguro si se sigue el programa del curso pero sí que se aprende mucho en un curso del cual uno no espera mucho. Se aprende mucho de las diversas áreas de la carrera y fuera de esta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'e5ef75d4981c49fc3493a3597f0c516028a7ca0482cfda2f5213098cd5ba8b7b'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'Excelente persona y excelente profe. Las clases siempre son diferentes una de la otra. Trae invitados a hablar de temas muy interesantes y útiles.Ayuda mucho con los trabajos y el proyecto. Es realmente fácil pasar el curso y hasta da gusto ir a clase. Recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '26179ad7988ad0dc6269e8f36ec5b77eca48a18df8e5331ea4975ca2dbab5cae'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'Lo peor para verano. La mitad de la clase no pasó el curso porque el Mae pensó que lo que se hacía en un semestre se podía hacer en 1 mes. Fue lo peor. Examenes súper volados y califica demasiado rudo. Es una teja como persona pero como profesor nada que ver. Quedar a más de la mitad del grupo no.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6905833e849dcf42582780baf96537648fb6238a27d26c85c51e0d03b5257392'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'El profe es muy apasionado por lo que hace, las clases son muy entretenidas, se aprende sobre temas diversos, los invitados especiales son muy interesantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'f5484cdad3c98d03996c446b4a7f036a50b9e15c299486ed9853b64a9bfad5cc'::TEXT, ARRAY[1156]::BIGINT[]),
    (579::BIGINT, 'De los mejores profesores que he tenido! No es un curso fácil el pone ejercicios que lo hacen pensar a uno pero eso hace el curso muy entretenido y se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-21T00:00:00+00:00'::TIMESTAMPTZ, 'f9347ada1d09397ef54c01ea36ff98a1f0eb998c4c67c8c53c2877c24293bcb7'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Increíble el curso, aprendí mucho aunque no sea un curso duro. Es una excelente persona, deja trabajos para tomar conciencia, no por dejarlos. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'a8ae69987ebcc5492370d4621c84b8595bcea5b08131de44c7060ce1853a5acb'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'Excelente profesor, tiene mucha paciencia y las clases son entretenidas. Se aprende mucho con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '6368b14dc81ab3b565ddfafba3cd5b1569f7ac4635f7ab63c1574f2a40fb28b8'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Muy fácil, en especial en este tipo de cursos que no requieren mucho tiempo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '903ae1b82de3cc82203da9aa5ad2844b0ff612a7dd07d56c7c724cf514f007b3'::TEXT, ARRAY[1157, 1156, 2545]::BIGINT[]),
    (579::BIGINT, 'El mejor profesor que pude escoger. C:'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'c4bc73ed229608d066eee0c7e89e1ea529b8d6f61bfce9446984aaab7c362e95'::TEXT, ARRAY[1249]::BIGINT[]),
    (579::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '15c84dc715269a3a6fc7d524312dbd4daaf5a4f3963495943d3fcb5037a0d047'::TEXT, ARRAY[315, 4866]::BIGINT[]),
    (579::BIGINT, 'Excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '20005375f7aa621398de86ddfa9750c986a4f3629e49d1c0cd834236c54155ef'::TEXT, ARRAY[1249]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
